SELECT

FROM finance_fund_holding h
LEFT JOIN finance_account a ON a.id = h.account_id AND a.deleted = 0 AND a.user_id = h.user_id

    h.deleted = 0
    AND h.user_id = #{userId}

        AND h.fund_name LIKE CONCAT('%', #{dto.fundName}, '%')


        AND h.account_id = #{dto.accountId}


        AND h.fund_category = #{dto.fundCategory}


        AND h.quote_status = #{dto.quoteStatus}


        AND h.enabled = #{dto.enabled}


ORDER BY h.sort_order ASC, h.id DESC

SELECT COUNT(1)
FROM finance_fund_holding
WHERE deleted = 0 AND account_id = #{accountId} AND user_id = #{userId}
